import logging

from taf.collectors.core import core
from robot.utils.robottypes import is_truthy
from .factory import DcapTraceCollectorFactory

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class dcap(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    @staticmethod
    def _prepare_configuration(parameters, boolean_parameters):
        configuration = {}
        for key, value in parameters.items():
            if value is not None:
                if key in boolean_parameters:
                    configuration[key] = is_truthy(value)
                else:
                    configuration[key] = value
        return configuration

    def create_dcap_trace_collector(
            self,
            name,
            trace,
            dcap=None,
            hops=None,
            invalidate_bts_info_cache=None):
        """
        Create DCAP trace collector.

        :param str name: name of collector
        :param dict dcap: (optional) DCAP configuration

            * `host` str: DCAP host, default: "127.0.0.1"
            * `port` str: DCAP port, default: 9443
            * `username` str: DCAP user, default: "dcapuser"
            * `password` str: DCAP password, default: "dcapadmin!"
            * `rd_version` str: taf.sw.dcap.rd DcapConnection version , default: "dcapv3"
            * `secure` bool: DCAP connection via https, default: True

        :param dict trace: trace configuration,
            see `<https://taf-sw-dcap-rd.docs.taf.ute.nsn-rdnet.net/en/latest/interfaces/interface.html#taf.sw.dcap.rd.interface.rd.start_trace>`_

            * `wait_for_activation` bool: wait for state "running" before returning from start trace, default: True

        :param dict hops: (optional) Proxy host details. This dict can be nested via another *proxy* entry.
                          The default entry in this dict is port=22.
                          It is possible to specify a modified dict by only giving the non-default entries and/or the
                          additional entry for *proxy*.

        :param bool invalidate_bts_info_cache: (optional)
            Controls whether to use the cached BTS info or fetch fresh data.
            * If not provided or is set to false, dry-run uses cache for BTS info requests.
            * Should be true if BTS configuration has been recently changed, like after a BTS configuration change.
            * With "invalidate_bts_info_cache": true, response time is about 10 seconds as BTS must be queried.
              With false, it takes only milliseconds.

        At Setup Collectors precondition is checked and cached for 5 minutes. If Start Collectors is
        called during precondition is cached, start is about 20 seconds faster.

        .. code-block:: robotframework

            *** Settings ***
            Library    taf.collectors.dcap

            *** Test Cases ***
            Collect C-plane Traces

                &{bts}=  Create Dictionary
                ...  host=10.0.1.2
                ...  port=443
                ...  username=${tl.gnbs[0].cu.oam_http_connection_details.username}
                ...  password=${tl.gnbs[0].cu.oam_http_connection_details.password}

                @{gnb_custom_profile}=  Create List  cp_5g

                &{trace}=  Create Dictionary
                ...  bts=${bts}
                ...  gnb_custom_profile=${gnb_custom_profile}

                Create DCAP Trace Collector
                ...  name=dcap
                ...  trace=${trace}

                Setup Collectors   names=dcap
                Start Collectors   names=dcap
                sleep    10s
                Stop_collectors     names=dcap
                Collect Collectors  names=dcap
                [teardown]  Teardown Collectors  names=dcap


        .. code-block:: robotframework

            *** Settings ***
            Library    taf.collectors.dcap

            *** Test Cases ***
            Collect C-plane Traces

                &{bts}=  Create Dictionary
                ...  host=10.0.1.2
                ...  port=443
                ...  username=${tl.gnbs[0].cu.oam_http_connection_details.username}
                ...  password=${tl.gnbs[0].cu.oam_http_connection_details.password}

                @{gnb_custom_profile}=  Create List  cp_5g

                &{trace}=  Create Dictionary
                ...  bts=${bts}
                ...  gnb_custom_profile=${gnb_custom_profile}

                &{hops}=  Create Dictionary
                ...  host=${tl.test_pcs[1].default_ssh_connection_details.addr}
                ...  user=${tl.test_pcs[1].default_ssh_connection_details.username}
                ...  password=${tl.test_pcs[1].default_ssh_connection_details.password}

                Create DCAP Trace Collector
                ...  name=dcap
                ...  trace=${trace}
                ...  hops=${hops}

                Setup Collectors   names=dcap
                Start Collectors   names=dcap
                sleep    10s
                Stop_collectors     names=dcap
                Collect Collectors  names=dcap
                [teardown]  Teardown Collectors  names=dcap


        .. code-block:: robotframework

            *** Settings ***
            Library    taf.collectors.dcap

            *** Test Cases ***
            Collect C-plane Traces

                &{vcu}=  Create Dictionary
                ...  host=192.168.100.129
                ...  port=443
                ...  username=Nemuadmin
                ...  password=Nokia@123

                &{vdu}=  Create Dictionary
                ...  host=192.168.255.129
                ...  port=443
                ...  username=Nemuadmin
                ...  password=Nokia@123

                @{bts_list}=  Create List  ${vcu}  ${vdu}

                @{vcu_custom_profile}=  Create List  controlPlane5gVcu

                @{vdu_custom_profile}=  Create List  controlPlane5gVdu

                &{vran_trace}=  Create Dictionary
                ...  bts=${bts_list}
                ...  vcu_custom_profile=${vcu_custom_profile}
                ...  vdu_custom_profile=${vdu_custom_profile}

                Create DCAP Trace Collector
                ...  name=dcap
                ...  trace=${vran_trace}

                Setup Collectors   names=dcap
                Start Collectors   names=dcap
                sleep    10s
                Stop_collectors     names=dcap
                Collect Collectors  names=dcap
                [teardown]  Teardown Collectors  names=dcap
        """
        parameters={
            "name": name,
            "trace": trace,
            "invalidate_bts_info_cache": invalidate_bts_info_cache
        }
        boolean_parameters = ['invalidate_bts_info_cache']
        configuration = self._prepare_configuration(
            parameters=parameters,
            boolean_parameters=boolean_parameters
        )
        if dcap is not None:
            if 'port' in dcap:
                dcap['port'] = int(dcap['port'])
            configuration["dcap"] = dcap
        if hops is not None:
            configuration["hops"] = hops
        logger.info("Creating DCAP trace collector with alias name %s", name)
        collector = DcapTraceCollectorFactory().create(
            configuration=configuration,
            existing_arguments={})
        logger.info("DCAP trace collector created successfully")
        self.set_alias(name, collector)
